export function LotusBloom({ scale = 1 }: { scale?: number }) {
  return (
    <g transform={`translate(0 0) scale(${scale})`}>
      {[-60, -30, 0, 30, 60].map((angle) => (
        <ellipse key={angle} className="r" cx="0" cy="-14" rx="6" ry="15" transform={`rotate(${angle} 0 0)`} />
      ))}
    </g>
  );
}

export function CornerMark({ size }: { size: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 60 60" aria-hidden="true">
      <path className="cs" d="M4 56 V30 Q4 4 30 4 H56" fill="none" strokeWidth="1.6" />
      <path className="cs" d="M12 56 V34 Q12 12 34 12 H56" fill="none" strokeWidth="1" />
      <g transform="translate(14 14)">
        {[0, 72, 144, 216, 288].map((angle) => (
          <ellipse key={angle} className="cr" cx="0" cy="-6" rx="3" ry="7" transform={`rotate(${angle})`} />
        ))}
        <circle className="cr" r="3" />
      </g>
    </svg>
  );
}

function scallops(width: number) {
  const span = 130;
  const count = Math.ceil(width / span) + 1;
  return Array.from({ length: count }, (_, scallop) => {
    const start = scallop * span;
    return Array.from({ length: 17 }, (_, index) => {
      const t = index / 16;
      return {
        cx: start + 7.2 + t * (span - 14.4),
        cy: 16.3 + Math.sin(t * Math.PI) * 23.7,
        key: `${scallop}-${index}`,
      };
    });
  }).flat();
}

function drops(width: number) {
  const span = 130;
  const count = Math.ceil(width / span) + 1;
  return Array.from({ length: count }, (_, index) => index * span);
}

export function PaperFilters({ emboss, deboss, grain }: { emboss: string; deboss: string; grain: string }) {
  return (
    <svg width="0" height="0" className="pt-filters" aria-hidden="true">
      <defs>
        <filter id={emboss} x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur in="SourceAlpha" stdDeviation="1.1" result="b" />
          <feOffset in="b" dx="1.6" dy="2.2" result="o1" />
          <feFlood style={{ floodColor: "var(--sh)" }} />
          <feComposite in2="o1" operator="in" result="s" />
          <feOffset in="b" dx="-1.3" dy="-1.3" result="o2" />
          <feFlood style={{ floodColor: "var(--hl)" }} />
          <feComposite in2="o2" operator="in" result="h" />
          <feMerge>
            <feMergeNode in="s" />
            <feMergeNode in="h" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        <filter id={deboss} x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur in="SourceAlpha" stdDeviation="1" result="b" />
          <feOffset in="b" dx="-1.4" dy="-1.6" result="o1" />
          <feFlood style={{ floodColor: "var(--sh)" }} />
          <feComposite in2="o1" operator="in" result="s" />
          <feOffset in="b" dx="1.2" dy="1.2" result="o2" />
          <feFlood style={{ floodColor: "var(--hl)" }} />
          <feComposite in2="o2" operator="in" result="h" />
          <feMerge>
            <feMergeNode in="h" />
            <feMergeNode in="s" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        <filter id={grain}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="2" stitchTiles="stitch" />
          <feColorMatrix values="0 0 0 0 0.35  0 0 0 0 0.28  0 0 0 0 0.2  0 0 0 0.09 0" />
        </filter>
      </defs>
    </svg>
  );
}

export function PaperScene({ desk, grain }: { desk: boolean; grain: string }) {
  const width = desk ? 1440 : 390;
  const height = desk ? 900 : 844;
  const palace = desk ? 1.32 : 0.93;
  const palaceX = width / 2 - 200 * palace;
  const palaceY = desk ? 342 : 362;
  const beads = scallops(width);
  const hangs = drops(width);
  const pondY = desk ? 810 : 738;
  const pondRx = desk ? 470 : 140;
  const pondRy = desk ? 40 : 26;
  const peacockScale = desk ? 1.55 : 0.52;
  const peacockY = desk ? 810 : 814;
  const leftPeacock = desk ? 280 : 78;
  const rightPeacock = desk ? 1160 : 312;

  return (
    <svg className="pt-scene" viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="xMidYMid slice" aria-hidden="true">
      <g>
        <path className="rs" d={`M0 10 H${width}`} strokeWidth="4" />
        {beads.map((bead) => (
          <circle key={bead.key} className="r" cx={bead.cx} cy={bead.cy} r="5.2" />
        ))}
        {hangs.map((x, index) => (
          <g key={x} className="pt-sway" style={{ animationDelay: `${-(index * 0.7)}s` }}>
            <rect className="r" x={x - 1} y="10" width="2" height="26" />
            <circle className="r" cx={x} cy="40" r="4.5" />
            <circle className="r" cx={x} cy="50" r="4.5" />
            <circle className="r" cx={x} cy="60" r="4.5" />
            <path className="r" d={`M${x - 7} 64 Q${x} 90 ${x + 7} 64 Z`} />
          </g>
        ))}
        <Vine x={desk ? 50 : 16} height={height} />
        <Vine x={desk ? width - 50 : width - 16} height={height} flip />
        <g transform={`translate(${palaceX} ${palaceY}) scale(${palace})`}>
          <Palace />
        </g>
        <ellipse className="d" cx={width / 2} cy={pondY} rx={pondRx} ry={pondRy} />
        <ellipse className="ds" cx={width / 2} cy={pondY} rx={pondRx * 0.7} ry={pondRy * 0.55} fill="none" strokeWidth="1.5" />
        {[0.28, 0.5, 0.72].map((spot, index) => {
          const bloom = index === 1 ? (desk ? 1.5 : 0.9) : desk ? 1.25 : 0.75;
          return (
            <g key={spot}>
              <ellipse className="r" cx={width * spot} cy={pondY + 4} rx={desk ? 75 : 22} ry={desk ? 13 : 8} />
              <g transform={`translate(${width * spot} ${pondY + 2}) scale(${bloom})`}>
                <LotusBloom />
              </g>
            </g>
          );
        })}
        <g transform={`translate(${leftPeacock} ${peacockY}) scale(${peacockScale})`}>
          <Peacock />
        </g>
        <g transform={`translate(${rightPeacock} ${peacockY}) scale(${-peacockScale} ${peacockScale})`}>
          <Peacock />
        </g>
      </g>
      <rect width="100%" height="100%" filter={`url(#${grain})`} style={{ mixBlendMode: "multiply" }} />
    </svg>
  );
}

function Vine({ x, height, flip = false }: { x: number; height: number; flip?: boolean }) {
  const sign = flip ? -1 : 1;
  const leaves = Array.from({ length: 9 }, (_, index) => {
    const t = index / 8;
    const y = height - 80 - t * (height - 230);
    const sway = Math.sin(index * 1.7) * 16 * sign;
    return { y, x: x + sway, rot: index % 2 ? 40 : -40, bud: index % 3 === 2, key: index };
  });
  const d = `M${x} ${height - 8} C ${x + 28 * sign} ${height * 0.72} ${x - 16 * sign} ${height * 0.42} ${x + 8 * sign} 150`;
  return (
    <g>
      <path className="rs" d={d} strokeWidth="3" fill="none" />
      {leaves.map((leaf) => (
        <g key={leaf.key} transform={`translate(${leaf.x} ${leaf.y}) rotate(${leaf.rot})`}>
          <ellipse className="r" cx="0" cy="0" rx="5" ry="11" />
          {leaf.bud ? <circle className="r" cx="8" cy="-6" r="5" /> : null}
        </g>
      ))}
    </g>
  );
}
